INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('2393d072-0efe-4429-9565-af3f64f9c3e6', 'Parking', '13', 'Décima tercera', 'OBLIGACIONES ESPECIALES', E'- The subtenant''s users/customers can use the shopping center''s parking area.\n- The sublandlord must provide at least 200 non-exclusive parking spaces for these users/customers.\n- There will be no charge for using these parking spaces unless the sublandlord decides to operate and control the parking, either directly or through a third party.\n- If the parking is operated and controlled, the subtenant''s users/customers will receive the same benefits as the sublandlord''s customers.', 'Permitir a los usuarios/clientes de EL SUBARRENDATARIO el uso del área de estacionamiento del Centro Comercial, para lo cual, LA SUBARRENDADORA se obliga a contar con un mínimo no exclusivo de 200 (doscientos) cajones de estacionamiento para sus usuarios/clientes de EL SUBARRENDATARIO. El uso de estos cajones de estacionamiento no tendrá costo alguno a cargo de los usuarios/clientes de EL SUBARRENDATARIO, salvo que en algún determinado momento LA SUBARRENDADORA decida por si o a través de un tercero operar y controlar el estacionamiento del Centro Comercial, en dicho supuesto, los usuarios/clientes de EL SUBARRENDATARIO gozará de los mismos beneficios de los que goce la clientela de LA SUBARRENDADORA.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('2393d072-0efe-4429-9565-af3f64f9c3e6', 'Promotional booths', '13', 'Décima Tercera', 'OBLIGACIONES ESPECIALES', E'- The subtenant is allowed to set up a maximum of 2 promotional pre-sale modules.\n- Each module can be up to 6 square meters in size.\n- The modules can operate 30 days before and 30 days after the opening of the commercial area.\n- Modules can be placed during the shopping center''s business hours.\n- Placement can be at the entrance of the commercial area or in available space within the shopping center.\n- The subtenant must ensure that the modules do not obstruct or block any entrances or exits.', 'Permitir a EL SUBARRENDATARIO la colocación de máximo de 2 (dos) módulos promocionales de preventa con una superficie no mayor a 6 (seis) metros cuadrados, mismo que estará en funcionamiento durante 30 (treinta) días anteriores y 30 (treinta) días posteriores a la apertura de EL ÁREA COMERCIAL. Este módulo podrá ser colocado en horas hábiles del Centro Comercial, ya sea en la entrada de EL ÁREA COMERCIAL en el espacio disponible del Centro Comercial que se encuentre en eses momento. En todo momento EL SUBARRENDATARIO se compromete a no obstruir o dificultar el paso o bloquear entradas o salidas.');
