Solidaridad 00000","map_addr_1":"Lote 002-2 Manzana 184 Avenida Constituyentes","map_addr_2":"GYM","map_city_state_zip":"Quintana Roo, Ejido de Playa del Carmen, Municipio de Solidaridad 00000","grid_brand":"Planet Fitness","is_next_percent_rent_payment":"No","location_created_at":"2026-09-22 16:43:34","active_lease_count_over_time":64691,"location_count_over_time":71580,"remaining_rent_liability_over_time":64691}'::jsonb);
INSERT INTO leases (id, location_id, tenant_company_id, lease_name, lease_type, is_sub_lease, estatus, acquisition_type, lease_classification, rent_commencement_date, delivery_date, expiration_date, expiration_date_including_options, is_month_to_month, number_of_options, each_option_years, remaining_options, remaining_options_years, renewal_notice_period_start, renewal_notice_deadline, renewal_notice_intention, length_of_lease_months, landlord_nombre, landlord_parent_company, landlord_vendor_id, landlord_address1, landlord_address2, landlord_city, landlord_state, landlord_zip, landlord_country, landlord_poc_nombre, landlord_poc_telefono, landlord_poc_email, grace_period_dias, late_fee_type, late_fee_monto, security_deposit, rental_prepayments, rental_prepayments_detalle, remaining_lease_liability, percent_rent_yn, atributos_extra) VALUES ('b646fb20-4002-463e-841d-c8e62f2d22ec', '6294e289-e760-4843-9b44-63d1c8ccfa1c', '83602737-ca9f-417e-b1ac-19d0ad371be6', 'Playa del Carmen Misión de las Flores Lease: Inmobiliaria Kira, S.A. de C.V.', NULL, true, 'activo', 'Lease', NULL, NULL, NULL, NULL, NULL, false, 2, NULL, 0, NULL, NULL, NULL, 'Send Notice to Renew', NULL, 'Inmobiliaria Kira, S.A. de C.V.', NULL, NULL, 'Avenida Constituyentes 1150,', NULL, 'Colonia Lomas Altas, Miguel Hidago', 'Ciudad de México', '11950', 'MX', NULL, NULL, NULL, 120, NULL, NULL, NULL, 618000, 'La arrendataria debe pagar al arrendador, en la fecha de entrega del local, un monto equivalente a dos meses de renta ($618,000 más IVA). Este pago se aplicará a los primeros dos meses de renta una vez que termine el periodo de gracia o desde que inicie operaciones el negocio, lo que ocurra primero.', NULL, true, '{"lease_most_recent_note":"Yes","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1,"is_next_percent_rent_payment":"No","rent_commencement_date_original":"TBD","expiration_date_original":"TBD","expiration_date_including_options_original":"TBD"}'::jsonb);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('b646fb20-4002-463e-841d-c8e62f2d22ec', 'Fecha de Entrega del Local', 'La entrega del local se notificará con al menos 30 días de anticipación, pudiendo el arrendador prorrogarla hasta por 60 días, también podrá adelantarla con aviso previo de 15 días.', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('b646fb20-4002-463e-841d-c8e62f2d22ec', 'Fecha de Firma del Contrato', '02 de marzo de 2026', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('b646fb20-4002-463e-841d-c8e62f2d22ec', 'Domicilio del Contrato', '"Playa del Carmen Misión de las Flores" con domicilio en la Avenida Constituyentes sin número, Lote 002-2, Manzana 184, entre Avenida Lilis y Paseo del Mayab en el aparcelamiento del Ejido de Playa del Carmen, Municipio de Solidaridad estado de Quintana Roo', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('b646fb20-4002-463e-841d-c8e62f2d22ec', 'Vigencia', '10 años forzosos para ambas partes contados a partir de la Fecha de Entrega Efectiva del Local comercial.', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('b646fb20-4002-463e-841d-c8e62f2d22ec', 'Fecha de Inicio de Pago de Renta', 'A partir del vencimiento del Plazo de Gracia, o bien en la fecha que LA ARRENDATARIA inicie operaciones del NEGOCIO que será instalado en EL LOCAL COMERCIAL, lo que suceda primero.', 'America Gonzalez', NULL);
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('b646fb20-4002-463e-841d-c8e62f2d22ec', 'Extension period', '7', 'Cuarta', 'PLAZO', E'- The Tenant can extend the lease for an additional five years.\n- The Tenant must notify the Landlord at least 180 days before the current lease ends.\n- Both parties will review the economic terms for the extension.\n- Any rent increase cannot exceed 12.5% of the last minimum rent.', 'La ARRENDATARIA tendrá el derecho de prorrogar el presente Contrato por un periodo adicional de cinco (5) años, previa notificación al ARRENDADOR con al menos noventa (180) días de anticipación, para lo cual las partes revisaran bajo qué condiciones económicas se dará dicha prórroga ya que caso de acordar un incremento, este no podrá exceder del 12.5% (doce punto cinco por ciento) de la última Renta Mínima.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('b646fb20-4002-463e-841d-c8e62f2d22ec', 'Base Rent', '8', 'Sexta', 'IMPORTE DE LA RENTA DEL LOCAL COMERCIAL', E'- Once the Grace Period ends or when the Tenant starts business operations in the Commercial Space, whichever comes first, the Tenant will pay the Landlord the greater of the following amounts:\n  - $309,000.00 (Three Hundred Nine Thousand Pesos) plus applicable VAT (referred to as the "Minimum Rent").', E'A partir del vencimiento del Plazo de Gracia, o bien en la fecha que LA ARRENDATARIA inicie operaciones del NEGOCIO que será instalado en EL LOCAL COMERCIAL, lo que suceda primero, LA ARRENDATARIA pagará a EL ARRENDADOR, lo que resulte mayor entre las cantidades que se indican a continuación:\n\na) La cantidad de $309,000.00 (TRESCIENTOS NUEVE MIL PESOS 00/100 M.N.) más el I.V.A. correspondiente (en lo sucesivo la “Renta Mínima"); y');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('b646fb20-4002-463e-841d-c8e62f2d22ec', 'Common Area Maintenance Charges', '9', 'Séptima', 'CUOTA DE MANTENIMIENTO', E'- The tenant must pay a monthly "Maintenance Fee" to the account specified by the landlord.\n- This fee is 15% of the monthly rent the tenant is obligated to pay.\n- The fee will include Value Added Tax (VAT) and any other applicable taxes or charges as per current Mexican tax laws.', E'LA ARRENDATARIA se obliga a pagar mensualmente a la cuenta que en su momento le notifique por escrito EL ARRENDADOR por concepto de "Cuota de Mantenimiento", la cantidad que resulte de aplicar el 15% (quince por ciento) a la Renta mínima mensual que LA ARRENDATARIA tenga la obligación de pagar en el mes de que se trate, de conformidad con la Cláusula Octava de este Contrato.\n\nA la Cuota de Mantenimiento deberá agregarse el Impuesto al Valor Agregado (I.V.A.) o cualquier otro impuesto, derecho o aprovechamiento trasladable a terceros, que dispongan las leyes fiscales mexicanas vigentes, ya sean estas Federales, Estatales o Municipales.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('b646fb20-4002-463e-841d-c8e62f2d22ec', 'Incremento de Renta', '8', 'Sexta', 'IMPORTE DE LA RENTA DEL LOCAL COMERCIAL', E'- The rent paid by the tenant to the landlord will be adjusted annually.\n- The adjustment will match the percentage increase reported by the National Consumer Price Index.\n- This index is published by INEGI in the Official Gazette.\n- The adjustment considers the last 12-month period.', 'Las Partes convienen en que la RENTA que pagará LA ARRENDATARIA a EL ARRENDADOR, se ajustará anualmente en el mismo porcentaje de incremento que reporte el Índice Nacional de Precios al Consumidor publicado por el INEGI en el Diario Oficial de la Federación, considerando el último período de 12 (doce) meses al del incremento, y así sucesivamente.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('b646fb20-4002-463e-841d-c8e62f2d22ec', 'Late Fees', '9', 'Octava', 'FORMA Y LUGAR DE PAGO DE RENTA', E'- If the tenant fails to pay rent on time, they will incur a late interest charge.\n- The interest rate will be three times the 28-day Interbank Equilibrium Interest Rate (TIIE) published by the Bank of Mexico.\n- This interest is calculated from the due date until the full payment is made.', 'El incumplimiento por parte de LA ARRENDATARIA en el pago de la RENTA de conformidad a la presente cláusula, causará un interés moratorio equivalente a la tasa de Interés Interbancaria de equilibrio (TIIE) a 28 días, publicada por el Banco de México, multiplicada por 3 (tres), calculados desde la fecha en que debió haber sido pagada, hasta el día en que efectivamente se realice el pago total del adeudo.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('b646fb20-4002-463e-841d-c8e62f2d22ec', 'Parking', '10', 'Novena', 'OBLIGACIONES DEL ARRENDADOR', E'- If parking fees are charged according to local laws, the tenant (LA ARRENDATARIA) will receive a special rate for their customers.\n- This special parking rate cannot exceed $10.00 for the first 2 hours.\n- After 2 hours, customers must pay the regular parking rate.\n- The parking fee will be updated every 24 months if the shopping center increases its rates.\n- The tenant must install a ticket validation machine or compatible system at their own expense within 60 days of being notified that parking fees are allowed.\n- The landlord (EL ARRENDADOR) must ensure the required number of parking spaces as per the law.', E'En caso de que se cobre cuota por el uso de estacionamiento de conformidad con la legislación local, y adicional a lo indicado en el punto anterior, otorgar a LA ARRENDATARIA una tarifa preferencial para sus clientes, respecto a la cuota de estacionamiento vigente que se cobre en el Centro Comercial. Dicha cuota preferencial de estacionamiento no podrá ser mayor a $10.00 (Diez Pesos 00/100 M.N.) por las primeras 2 (dos) horas que permanezcan en el estacionamiento; una vez transcurridas las primeras 2 (dos) horas, los clientes de LA ARRENDATARIA deberán pagar la tarifa vigente que aplique. Dicho pago se deberá de actualizarse una vez que se implemente el cobro cada 24 (veinticuatro) meses, siempre y cuando el incremento se realice para el Centro Comercial.\n\nLA ARRENDATARIA quedará obligada a que a más tardar en un plazo de 60 (sesenta) días posteriores a que de acuerdo con la legislación local se permita el cobro por el uso del Estacionamiento del Centro Comercial y previa notificación por parte de EL ARRENDADOR, deberá instalar por su cuenta y su costo, una máquina Validadora de Boletos de estacionamiento, o bien un sistema de validación de boletos que sea compatible con el sistema de cobro de cuotas de estacionamiento que se encuentre operando en el Centro Comercial, el cual, previo a su instalación, deberá ser validado y autorizado por EL ARRENDADOR. \n\nAsimismo, EL ARRENDADOR, se obliga a contar con el número de cajones exigidos por la legislación correspondiente.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('b646fb20-4002-463e-841d-c8e62f2d22ec', 'Licencias y Permisos', '13', 'Décima Primera', 'DERECHOS DE LA ARRENDATARIA', E'- Si en 120 días desde la entrega del local, no se obtienen los permisos o servicios necesarios, la arrendataria puede:\n  - Terminar el contrato sin responsabilidad, y el arrendador debe devolver cualquier pago recibido.\n  - Acordar un nuevo plazo de 120 días para obtener los permisos.\n\n- Estas opciones son válidas si:\n  - La arrendataria demuestra que hizo las gestiones necesarias.\n  - La falta de permisos no es culpa de la arrendataria.\n  - Si se elige una opción, el arrendador tiene 60 días para intentar obtener los permisos o servicios necesarios.', E'Si en un plazo de 120 (ciento veinte) días naturales, contados a partir de entrega del LOCAL COMERCIAL a LA ARRENDATARIA, las autoridades y/o dependencias públicas y/o compañías correspondientes, no le han proporcionado los permisos y licencias y/o servicios con las especificaciones requeridas por LA ARRENDATARIA, la misma podrá, a su elección realizar las siguientes opciones:\n\na) Dar por terminado el presente Contrato, sin responsabilidad alguna para ninguna de las Partes, quedando obligado EL ARRENDADOR a devolver a LA ARRENDATARIA las cantidades que esta última le haya entregado a EL ARRENDADOR de conformidad al presente Contrato.\n\nb) Acordar un nuevo plazo de 120 (ciento veinte) días naturales, para la obtención de los permisos y licencias correspondientes. \n\nLo indicado en el inciso a y b anterior, operará siempre y cuando: i) LA ARRENDATARIA demuestre fehacientemente a EL ARRENDADOR que realizó las gestiones necesarias ante las autoridades correspondientes para la obtención de sus permisos, licencias y/o servicios; ii) que la no obtención de dichos permisos, licencias y/o servicios, no se deriva de una causa imputable a LA ARRENDATARIA, ya que de lo contrario LA ARRENDATARIA estará en incumplimiento de esta obligación; y iii) que una vez que LA ARRENDATARIA, haya agotado cualquiera de los plazos previstos en los incisos a y b anteriores, según el que haya elegido y le haya notificado por escrito a EL ARRENDADOR, este último agote un plazo máximo de 60 (sesenta) días naturales contados a partir de dicha notificación, para tratar de obtener los permisos y licencias y/o servicios con las especificaciones requeridas por LA ARRENDATARIA para su operación.\n\nEsto aplica siempre que la arrendataria demuestre que realizó las gestiones necesarias y que la falta de permisos no es imputable a ella. Adicionalmente, una vez notificado el arrendador, este contará con hasta 60 días para intentar obtener dichos permisos o servicios requeridos.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('b646fb20-4002-463e-841d-c8e62f2d22ec', 'Percentage Rent', '8', 'SEXTA', 'IMPORTE DE LA RENTA DE EL LOCAL COMERCIAL', E'- Once the Grace Period ends or when the Tenant starts business operations in the Commercial Premises, whichever comes first, the Tenant will pay the Landlord the greater of the following amounts:\n\n  - 5% of the Tenant''s Monthly Net Income from the Leased Premises, plus applicable VAT (referred to as "Variable Rent").\n\n- Monthly Net Income is defined as the total income the Tenant earns in the previous month from activities in the Commercial Premises, as specified in Clause Five, minus returns, cancellations, taxes, and bank fees from sales.', E'A partir del vencimiento del Plazo de Gracia, o bien en la fecha que LA ARRENDATARIA inicie operaciones del NEGOCIO que será instalado en EL LOCAL COMERCIAL, lo que suceda primero, LA ARRENDATARIA pagará a EL ARRENDADOR, lo que resulte mayor entre las cantidades que se indican a continuación:\n\nb) El 5.0% (cinco por ciento) de los Ingresos Netos Mensuales (según dicho término se define más adelante) que perciba el Arrendatario en el Local Arrendado, más el I.V.A. correspondiente (en lo sucesivo la "Renta Variable").\n\nPara efectos de este contrato, se entenderá como Ingresos Netos Mensuales, el importe de los ingresos totales que LA ARRENDATARIA obtenga en el mes inmediato anterior, derivado de las actividades que desarrolle en EL LOCAL COMERCIAL, de acuerdo al Destino que se establece al efecto en la Cláusula Quinta, descontando de éstos el importe correspondiente a devoluciones, cancelaciones, impuestos y comisiones bancarias de las ventas efectuadas.');
